# -*- coding: utf-8 -*-
"""Begriffe des Arbeitnehmererfinderrechts (ArbnErfG und Vergütungsrichtlinien). Felder wie concepts.py; `quellen` sind Nummern
der Vergütungsrichtlinien (arbnerfg.BEGRIFF_QUELLEN, `vrl:30`). Kategorie „Patent: Arbeitnehmererfindungen (ArbnErfG)“."""
from .arbnerfg import BEGRIFF_QUELLEN

AE = "Patent: Arbeitnehmererfindungen (ArbnErfG)"


def c(id, label, definition, erlaeuterung, norms=(), cases=(), related=()):
    return dict(id=id, label=label, kategorie=AE, definition=definition, erlaeuterung=erlaeuterung, norms=list(norms), cases=list(cases),
                ipwiki=[], related=list(related), quellen=list(BEGRIFF_QUELLEN.get(id, [])))


CONCEPTS = [
    c("arb_diensterfindung", "Diensterfindung (§ 4 Abs. 2 ArbnErfG)",
      "Diensterfindungen sind während der Dauer des Arbeitsverhältnisses gemachte Erfindungen, die entweder aus der dem Arbeitnehmer im Betrieb obliegenden Tätigkeit entstanden sind (Auftragserfindung) oder maßgeblich auf Erfahrungen oder Arbeiten des Betriebs beruhen (Erfahrungserfindung), § 4 Abs. 2 ArbnErfG.",
      "Erfindung im Sinne des Gesetzes ist nur, was patent- oder gebrauchsmusterfähig ist (§ 2 ArbnErfG); im Streit um die Vergütung genügt die Schutzfähigkeit im Zweifel, solange das Schutzrecht nicht rechtskräftig versagt ist. „Gemacht“ ist die Erfindung, wenn sie fertig ist, d. h. der Erfinder sie technisch ausführen kann. Nach dem Ausscheiden fertiggestellte Erfindungen sind frei, außer der Arbeitnehmer hat die Fertigstellung treuwidrig hinausgezögert.",
      norms=["§ 4 Abs. 2 ArbnErfG", "§ 2 ArbnErfG"], related=["arb_freie_erfindung", "arb_erfindungsmeldung", "arb_tvv"]),
    c("arb_freie_erfindung", "Freie Erfindung (§§ 4, 18, 19 ArbnErfG)",
      "Freie Erfindungen sind alle Erfindungen eines Arbeitnehmers, die keine Diensterfindungen sind (§ 4 Abs. 3 ArbnErfG), sowie frei gewordene Diensterfindungen (§ 8 ArbnErfG). Der Arbeitnehmer muss sie dem Arbeitgeber mitteilen (§ 18 ArbnErfG) und vor anderweitiger Verwertung ein nichtausschließliches Benutzungsrecht anbieten, wenn sie in den Arbeitsbereich des Betriebs fällt (§ 19 ArbnErfG).",
      "Die Mitteilungspflicht entfällt, wenn die Erfindung offensichtlich im Arbeitsbereich des Betriebs nicht verwendbar ist (§ 18 Abs. 3 ArbnErfG). Bestreitet der Arbeitgeber nicht binnen drei Monaten, dass die mitgeteilte Erfindung frei ist, kann er sie nicht mehr als Diensterfindung in Anspruch nehmen (§ 18 Abs. 2 ArbnErfG).",
      norms=["§ 4 Abs. 3 ArbnErfG", "§ 18 ArbnErfG", "§ 19 ArbnErfG"], related=["arb_diensterfindung", "arb_freigabe"]),
    c("arb_tvv", "Technischer Verbesserungsvorschlag (§§ 3, 20 ArbnErfG)",
      "Technische Verbesserungsvorschläge sind Vorschläge für technische Neuerungen, die nicht patent- oder gebrauchsmusterfähig sind (§ 3 ArbnErfG). Gewähren sie dem Arbeitgeber eine ähnliche Vorzugsstellung wie ein gewerbliches Schutzrecht (qualifizierter Verbesserungsvorschlag), hat der Arbeitnehmer einen Anspruch auf angemessene Vergütung, sobald der Arbeitgeber sie verwertet (§ 20 Abs. 1 ArbnErfG).",
      "Die Vorzugsstellung setzt eine faktische Monopolstellung voraus: Wettbewerber können die Neuerung nicht nachahmen, weil sie geheim bleibt oder nicht analysierbar ist (RL Nr. 29). Sie endet, sobald die Neuerung bekannt wird. Einfache Verbesserungsvorschläge regeln Tarifvertrag und Betriebsvereinbarung (betriebliches Vorschlagswesen, § 20 Abs. 2 ArbnErfG).",
      norms=["§ 3 ArbnErfG", "§ 20 ArbnErfG"], related=["arb_diensterfindung", "arb_verguetungsanspruch"]),
    c("arb_erfindungsmeldung", "Erfindungsmeldung (§ 5 ArbnErfG)",
      "Der Arbeitnehmer muss eine Diensterfindung unverzüglich gesondert in Textform melden und dabei kenntlich machen, dass es sich um die Meldung einer Erfindung handelt (§ 5 Abs. 1 ArbnErfG). Die Meldung beschreibt Aufgabe, Lösung und Zustandekommen und nennt Mitarbeiter und deren Anteil (§ 5 Abs. 2 ArbnErfG).",
      "Beanstandet der Arbeitgeber die Meldung nicht binnen zwei Monaten, gilt sie als ordnungsgemäß (§ 5 Abs. 3 ArbnErfG). Die ordnungsgemäße Meldung setzt die Viermonatsfrist der Inanspruchnahme in Gang (§ 6 Abs. 2 ArbnErfG). Eine Patentanmeldung des Arbeitgebers mit dem Arbeitnehmer als Erfinder kann eine fehlende Meldung ersetzen, wenn der Arbeitgeber dadurch die Kenntnis erlangt hat, die die Meldung vermitteln soll.",
      norms=["§ 5 ArbnErfG"], related=["arb_inanspruchnahme", "arb_diensterfindung"]),
    c("arb_inanspruchnahme", "Inanspruchnahme der Diensterfindung (§§ 6, 7 ArbnErfG)",
      "Der Arbeitgeber kann eine Diensterfindung durch Erklärung gegenüber dem Arbeitnehmer in Anspruch nehmen (§ 6 Abs. 1 ArbnErfG); seit dem 1.10.2009 gilt sie als in Anspruch genommen, wenn er sie nicht binnen vier Monaten nach Eingang der ordnungsgemäßen Meldung in Textform freigibt (§ 6 Abs. 2 ArbnErfG). Mit der Inanspruchnahme gehen alle vermögenswerten Rechte auf den Arbeitgeber über (§ 7 Abs. 1 ArbnErfG).",
      "Für vor dem 1.10.2009 gemeldete Erfindungen gilt altes Recht (§ 43 Abs. 3 ArbnErfG): schriftliche Inanspruchnahme binnen vier Monaten, beschränkt (nur Benutzungsrecht) oder unbeschränkt; ohne Erklärung wurde die Erfindung frei. Verfügungen des Arbeitnehmers vor der Inanspruchnahme sind dem Arbeitgeber gegenüber unwirksam, soweit sie seine Rechte beeinträchtigen (§ 7 Abs. 2 ArbnErfG).",
      norms=["§ 6 ArbnErfG", "§ 7 ArbnErfG", "§ 43 Abs. 3 ArbnErfG"], related=["arb_erfindungsmeldung", "arb_freigabe", "arb_verguetungsanspruch", "arb_altrecht"]),
    c("arb_freigabe", "Freigabe (§ 8 ArbnErfG)",
      "Gibt der Arbeitgeber eine Diensterfindung durch Erklärung in Textform frei, wird sie frei (§ 8 S. 1 ArbnErfG); der Arbeitnehmer kann über sie ohne die Beschränkungen der §§ 18, 19 ArbnErfG verfügen (§ 8 S. 2 ArbnErfG).",
      "Die Freigabe ist eine einseitige, empfangsbedürftige Erklärung. Sie ist zu unterscheiden von der Aufgabe eines bereits angemeldeten Schutzrechts nach § 16 ArbnErfG (Übertragungsangebot) und von der Freigabe für das Ausland (§ 14 Abs. 2 ArbnErfG).",
      norms=["§ 8 ArbnErfG"], related=["arb_inanspruchnahme", "arb_aufgabe_schutzrecht"]),
    c("arb_verguetungsanspruch", "Vergütungsanspruch (§ 9 ArbnErfG)",
      "Der Arbeitnehmer hat gegen den Arbeitgeber einen Anspruch auf angemessene Vergütung, sobald dieser die Diensterfindung in Anspruch genommen hat (§ 9 Abs. 1 ArbnErfG). Maßgebend sind die wirtschaftliche Verwertbarkeit, Aufgaben und Stellung des Arbeitnehmers im Betrieb und der Anteil des Betriebs am Zustandekommen (§ 9 Abs. 2 ArbnErfG).",
      "Die Vergütungsrichtlinien (§ 11 ArbnErfG) setzen das in die Formel Vergütung = Erfindungswert × Anteilsfaktor um (RL Nr. 39). Der Anspruch ist eine Sonderleistung neben dem Arbeitslohn; er entsteht dem Grunde nach mit der Inanspruchnahme und wird mit der Verwertung fällig. Hilfsansprüche auf Auskunft und Rechnungslegung folgen aus § 242 BGB.",
      norms=["§ 9 ArbnErfG", "§ 11 ArbnErfG"], related=["arb_erfindungswert", "arb_anteilsfaktor", "arb_festsetzung", "arb_auskunft"]),
    c("arb_erfindungswert", "Erfindungswert",
      "Der Erfindungswert ist der Preis, den der Arbeitgeber einem freien Erfinder für die Erfindung zahlen würde (wirtschaftliche Verwertbarkeit, § 9 Abs. 2 ArbnErfG). Er wird nach der Lizenzanalogie, dem erfassbaren betrieblichen Nutzen oder durch Schätzung ermittelt (RL Nr. 3).",
      "Vorrang hat die Lizenzanalogie, wenn die Branche Lizenzsätze kennt (RL Nr. 5). Bei Lizenzvergabe oder Verkauf ist der Erfindungswert die Nettoeinnahme (RL Nr. 14, 16). Nicht verwertete, aber verwertbare Erfindungen sind nach den unausgenutzten Möglichkeiten zu bewerten (RL Nr. 24); Vorratspatente nach RL Nr. 21.",
      norms=["§ 9 Abs. 2 ArbnErfG"], related=["arb_lizenzanalogie", "arb_anteilsfaktor", "arb_verguetungsanspruch", "arb_vorratspatent"]),
    c("arb_lizenzanalogie", "Lizenzanalogie (RL Nr. 6 bis 11)",
      "Bei der Lizenzanalogie ist der Erfindungswert die Bezugsgröße (meist der Umsatz mit erfindungsgemäßen Produkten) multipliziert mit dem Lizenzsatz, den vernünftige Vertragspartner für eine vergleichbare freie Erfindung vereinbart hätten (RL Nr. 6, 7; Formel E = B × L, RL Nr. 39).",
      "Zu klären sind die technisch-wirtschaftliche Bezugsgröße (ganze Vorrichtung oder wertbeeinflusster Teil, RL Nr. 8), der branchenübliche Lizenzsatz (Anhaltspunkte RL Nr. 10) und bei hohen Umsätzen die Abstaffelung (RL Nr. 11), die nur bei branchenüblicher Kausalität der Umsätze aus anderen Gründen als der Erfindung angewandt wird. Ein Abschlag „weil Diensterfindung“ ist unzulässig (RL Nr. 9); er gehört in den Anteilsfaktor.",
      norms=["§ 9 Abs. 2 ArbnErfG", "§ 11 ArbnErfG"], related=["arb_erfindungswert", "arb_anteilsfaktor"]),
    c("arb_anteilsfaktor", "Anteilsfaktor (RL Nr. 30 bis 38)",
      "Der Anteilsfaktor ist der Prozentsatz des Erfindungswerts, der dem Arbeitnehmer verbleibt, weil er keine freie Erfindung gemacht hat. Er ergibt sich aus der Summe der Wertzahlen für die Stellung der Aufgabe (a, RL Nr. 31), die Lösung der Aufgabe (b, RL Nr. 32) und die Aufgaben und Stellung im Betrieb (c, RL Nr. 33 bis 36) nach der Tabelle in RL Nr. 37.",
      "Typisch sind Anteilsfaktoren zwischen 10 und 25 %. Je höher die Leistungserwartung an den Arbeitnehmer und je mehr der Betrieb beigetragen hat, desto niedriger der Faktor. Derselbe Gesichtspunkt darf nicht doppelt (im Erfindungswert und im Anteilsfaktor) berücksichtigt werden (RL Nr. 2).",
      norms=["§ 9 Abs. 2 ArbnErfG"], related=["arb_erfindungswert", "arb_verguetungsanspruch"]),
    c("arb_festsetzung", "Feststellung und Festsetzung der Vergütung (§ 12 ArbnErfG)",
      "Art und Höhe der Vergütung sollen in angemessener Frist nach der Inanspruchnahme durch Vereinbarung festgestellt werden (§ 12 Abs. 1 ArbnErfG). Kommt keine Vereinbarung zustande, muss der Arbeitgeber die Vergütung durch begründete Erklärung in Textform festsetzen und entsprechend zahlen, spätestens drei Monate nach Erteilung des Schutzrechts (§ 12 Abs. 3 ArbnErfG).",
      "Widerspricht der Arbeitnehmer nicht binnen zwei Monaten in Textform, wird die Festsetzung verbindlich (§ 12 Abs. 4 ArbnErfG). Bei mehreren Erfindern ist die Vergütung für jeden gesondert festzustellen (§ 12 Abs. 2 ArbnErfG). Vereinbarung und Festsetzung können wegen erheblicher Unbilligkeit unwirksam sein (§ 23 ArbnErfG) oder an wesentlich veränderte Umstände angepasst werden (§ 12 Abs. 6 ArbnErfG).",
      norms=["§ 12 ArbnErfG"], related=["arb_verguetungsanspruch", "arb_anpassung", "arb_unbilligkeit"]),
    c("arb_anpassung", "Anpassung der Vergütung (§ 12 Abs. 6 ArbnErfG)",
      "Arbeitgeber und Arbeitnehmer können voneinander die Einwilligung in eine andere Regelung der Vergütung verlangen, wenn sich Umstände wesentlich ändern, die für die Feststellung oder Festsetzung maßgebend waren (§ 12 Abs. 6 S. 1 ArbnErfG). Eine bereits geleistete Vergütung kann nicht zurückgefordert werden (§ 12 Abs. 6 S. 2 ArbnErfG).",
      "Wesentlich ist eine Änderung, die ein Festhalten an der Regelung unzumutbar macht (Gedanke der Störung der Geschäftsgrundlage), etwa eine unerwartete Umsatzentwicklung bei einer Pauschalabfindung. Die Nichtigerklärung des Schutzrechts wirkt für die Zukunft; bis dahin bleibt die Vergütung geschuldet (RL Nr. 43).",
      norms=["§ 12 Abs. 6 ArbnErfG"], related=["arb_festsetzung", "arb_unbilligkeit"]),
    c("arb_unbilligkeit", "Unbilligkeit (§ 23 ArbnErfG)",
      "Vereinbarungen über Diensterfindungen, freie Erfindungen oder Verbesserungsvorschläge, die nach dem Gesetz zulässig sind, sind unwirksam, soweit sie in erheblichem Maße unbillig sind; dasselbe gilt für die Festsetzung der Vergütung (§ 23 Abs. 1 ArbnErfG). Die Unbilligkeit muss spätestens bis zum Ablauf von sechs Monaten nach Beendigung des Arbeitsverhältnisses in Textform geltend gemacht werden (§ 23 Abs. 2 ArbnErfG).",
      "Maßstab ist ein objektives Missverhältnis zwischen der vereinbarten und der gesetzlich geschuldeten Vergütung zum Zeitpunkt der Vereinbarung; die Schiedsstelle geht bei einer Abweichung von etwa der Hälfte davon aus. Abzugrenzen von der Unabdingbarkeit des § 22 ArbnErfG (Vereinbarungen vor der Meldung) und von der Anpassung nach § 12 Abs. 6 ArbnErfG (spätere Änderung der Umstände).",
      norms=["§ 23 ArbnErfG", "§ 22 ArbnErfG"], related=["arb_festsetzung", "arb_anpassung"]),
    c("arb_schutzrechtsanmeldung", "Anmeldepflicht des Arbeitgebers (§§ 13, 14 ArbnErfG)",
      "Der Arbeitgeber ist verpflichtet und allein berechtigt, eine gemeldete Diensterfindung im Inland zur Erteilung eines Schutzrechts anzumelden, und zwar unverzüglich (§ 13 Abs. 1 ArbnErfG). Nach der Inanspruchnahme ist er berechtigt, sie auch im Ausland anzumelden (§ 14 Abs. 1 ArbnErfG); für Staaten, in denen er nicht anmelden will, muss er sie freigeben (§ 14 Abs. 2 ArbnErfG).",
      "Die Anmeldepflicht entfällt bei Freigabe, mit Zustimmung des Arbeitnehmers oder bei einem Betriebsgeheimnis nach § 17 ArbnErfG (§ 13 Abs. 2 ArbnErfG). Verletzt der Arbeitgeber sie, kann der Arbeitnehmer nach Fristsetzung selbst anmelden (§ 13 Abs. 3 ArbnErfG) und Schadensersatz verlangen.",
      norms=["§ 13 ArbnErfG", "§ 14 ArbnErfG", "§ 17 ArbnErfG"], related=["arb_aufgabe_schutzrecht", "arb_inanspruchnahme"]),
    c("arb_aufgabe_schutzrecht", "Aufgabe von Anmeldung oder Schutzrecht (§ 16 ArbnErfG)",
      "Will der Arbeitgeber vor Erfüllung des Vergütungsanspruchs die Anmeldung nicht weiterverfolgen oder das Schutzrecht nicht aufrechterhalten, muss er dies dem Arbeitnehmer mitteilen und ihm auf Verlangen und auf dessen Kosten das Recht übertragen (§ 16 Abs. 1 ArbnErfG). Verlangt der Arbeitnehmer nicht binnen drei Monaten die Übertragung, darf der Arbeitgeber das Recht aufgeben (§ 16 Abs. 2 ArbnErfG).",
      "Der Arbeitgeber kann sich bei der Mitteilung ein nichtausschließliches Benutzungsrecht gegen angemessene Vergütung vorbehalten (§ 16 Abs. 3 ArbnErfG). Lässt er ein Schutzrecht ohne Angebot verfallen, schuldet er Schadensersatz; die Pflicht besteht nur, solange der Vergütungsanspruch nicht vollständig erfüllt ist (z. B. durch Pauschalabfindung).",
      norms=["§ 16 ArbnErfG"], related=["arb_schutzrechtsanmeldung", "arb_freigabe"]),
    c("arb_schiedsstelle", "Schiedsstelle nach dem ArbnErfG (§§ 28 bis 36 ArbnErfG)",
      "Die Schiedsstelle beim DPMA kann in allen Streitfällen zwischen Arbeitgeber und Arbeitnehmer auf Grund des ArbnErfG angerufen werden; sie hat zu versuchen, eine gütliche Einigung herbeizuführen (§ 28 ArbnErfG). Sie macht einen Einigungsvorschlag, der verbindlich wird, wenn nicht binnen eines Monats schriftlich widersprochen wird (§ 34 Abs. 3 ArbnErfG).",
      "Das Verfahren ist kostenfrei (§ 36 ArbnErfG). Klage ist erst nach einem Schiedsverfahren zulässig (§ 37 Abs. 1 ArbnErfG), außer in den Fällen des § 37 Abs. 2 ArbnErfG, namentlich wenn der Arbeitnehmer aus dem Betrieb ausgeschieden ist. Ausschließlich zuständig für die Klage sind die Patentstreitkammern der Landgerichte (§ 39 Abs. 1 ArbnErfG).",
      norms=["§ 28 ArbnErfG", "§ 34 ArbnErfG", "§ 37 ArbnErfG", "§ 39 ArbnErfG"], related=["arb_verguetungsanspruch"]),
    c("arb_hochschulerfindung", "Hochschulerfindung (§ 42 ArbnErfG)",
      "Für Erfindungen der an einer Hochschule Beschäftigten gelten Sonderregeln: Publikationsfreiheit nach rechtzeitiger Anzeige (§ 42 Nr. 1 ArbnErfG), keine Meldepflicht bei Ablehnung der Offenbarung (§ 42 Nr. 2 ArbnErfG), Benutzungsrecht für Lehre und Forschung (§ 42 Nr. 3 ArbnErfG) und eine Vergütung von 30 % der durch die Verwertung erzielten Einnahmen (§ 42 Nr. 4 ArbnErfG).",
      "Die 30 % beziehen sich auf die Bruttoeinnahmen der Hochschule aus der Verwertung, ohne Abzug von Kosten und ohne Anteilsfaktor. Ob eine Einrichtung „Hochschule“ ist (etwa ein Universitätsklinikum), entscheidet die Verzahnung von Forschung, Lehre und Krankenversorgung, nicht die Rechtsform.",
      norms=["§ 42 ArbnErfG"], related=["arb_verguetungsanspruch", "arb_diensterfindung"]),
    c("arb_altrecht", "Übergangsrecht: Erfindungen vor dem 1.10.2009 (§ 43 Abs. 3 ArbnErfG)",
      "Auf Erfindungen, die vor dem 1.10.2009 gemeldet wurden, sind die Vorschriften des ArbnErfG in der bis dahin geltenden Fassung anzuwenden (§ 43 Abs. 3 ArbnErfG). Maßgeblich ist der Zeitpunkt der Meldung, nicht der Fertigstellung.",
      "Altes Recht heißt vor allem: Inanspruchnahme nur durch schriftliche Erklärung binnen vier Monaten (sonst wird die Erfindung frei), Wahl zwischen beschränkter und unbeschränkter Inanspruchnahme, Schriftform statt Textform. Viele Einigungsvorschläge der Schiedsstelle betreffen noch Altfälle; ihre Aussagen zur Inanspruchnahme sind deshalb am Meldedatum zu messen.",
      norms=["§ 43 Abs. 3 ArbnErfG", "§ 6 ArbnErfG"], related=["arb_inanspruchnahme", "arb_erfindungsmeldung"]),
    c("arb_auskunft", "Auskunft und Rechnungslegung",
      "Zur Berechnung der Vergütung kann der Arbeitnehmererfinder vom Arbeitgeber Auskunft und Rechnungslegung nach § 242 BGB verlangen, soweit er die Angaben benötigt und der Arbeitgeber sie ohne unzumutbaren Aufwand geben kann.",
      "Umfang nach der Berechnungsmethode: bei der Lizenzanalogie Umsätze mit erfindungsgemäßen Produkten, nicht Gewinne oder Kosten; beim erfassbaren betrieblichen Nutzen weitergehende Kostenangaben (RL Nr. 5). Grenzen setzen Geheimhaltungsinteressen und die Verhältnismäßigkeit (BGH Türinnenverstärkung, Ramipril).",
      norms=["§ 9 ArbnErfG", "§ 12 ArbnErfG"], related=["arb_verguetungsanspruch", "arb_lizenzanalogie"]),
    c("arb_miterfinder", "Miterfinder und Miterfinderanteil",
      "Haben mehrere Arbeitnehmer an einer Diensterfindung mitgewirkt, ist die Vergütung für jeden gesondert festzustellen; der Arbeitgeber muss allen die Gesamthöhe und die Anteile bekanntgeben (§ 12 Abs. 2 ArbnErfG). Miterfinder ist, wer einen schöpferischen Beitrag zur Lösung geleistet hat; der Anteil bemisst sich nach dem Gewicht der Beiträge.",
      "Rein handwerkliche Mitwirkung nach Anweisung begründet keine Miterfinderschaft. Widerspricht ein Miterfinder der Festsetzung mit der Begründung, sein Anteil sei unrichtig, wird sie für alle unverbindlich (§ 12 Abs. 5 ArbnErfG). Die Erfinderbenennung im Patent (§ 37 PatG) ist für den Anteil nur ein Indiz.",
      norms=["§ 12 Abs. 2 ArbnErfG", "§ 12 Abs. 5 ArbnErfG"], related=["arb_festsetzung", "arb_verguetungsanspruch"]),
    c("arb_vorratspatent", "Vorrats-, Sperr- und nicht verwertete Patente (RL Nr. 18 bis 24)",
      "Auch nicht benutzte Diensterfindungen können einen Erfindungswert haben: Sperrpatente, die Wettbewerber von einer Nachahmung abhalten (RL Nr. 18), und Vorrats- oder Ausbaupatente, deren spätere Verwertung zu erwarten ist (RL Nr. 21). Wirtschaftlich nicht verwertbare Erfindungen haben keinen Erfindungswert (RL Nr. 22).",
      "Hält der Arbeitgeber ein Schutzrecht über eine Prüfungszeit von in der Regel drei bis fünf Jahren aufrecht, ohne es freizugeben, spricht eine tatsächliche Vermutung für einen Wert (RL Nr. 23). Die Schiedsstelle setzt für Vorratspatente meist einen Jahrespauschalbetrag an.",
      norms=["§ 9 Abs. 2 ArbnErfG"], related=["arb_erfindungswert", "arb_aufgabe_schutzrecht"]),
]
